graphify_commands:
for n in scripts_do_math_review_cycle_record_turn scripts_do_math_submission_validate_reference scripts_do_math_planning_apply_event_schedule scripts_do_math_planning_contract_review_current scripts_do_math_task_contracts_repetition_lineages scripts_do_math_submission_normalize_reference scripts_do_math_review_engine_reviewenginemixin_staged_review_candidate; do echo "== $n"; python .claude/skills/graphify/scripts/graph.py query "$n" --exact --relation calls 2>&1 | python -c "
import sys,json
raw=sys.stdin.read()
i=raw.find('\n{')
try:
  d=json.loads(raw[i+1:] if i>=0 else raw)
except Exception as e:
  print(raw[:600]); sys.exit()
nodes={x['id']:x for x in d.get('nodes',[])}
for e in d.get('edges',d.get('links',[])):
  s,t=e.get('source'),e.get('target')
  print(e.get('relation'), nodes.get(s,{}).get('label',s), '->', nodes.get(t,{}).get('label',t), nodes.get(s,{}).get('source_file'), nodes.get(s,{}).get('source_location'))
"; done
